def countdown(start):
    remaining = start
    while remaining > 0:
        yield remaining
        remaining -= 1

class Countdown:
    def __init__(self, start):
        self.remaining = start
    def __iter__(self):
        return self
    def __next__(self):
        if self.remaining <= 0:
            raise StopIteration
        value = self.remaining
        self.remaining -= 1
        return value

class MinuteError(ValueError):
    pass

def parse_minutes(text):
    try:
        value = int(text)
    except ValueError as error:
        raise MinuteError("whole minutes required") from error
    if not 1 <= value <= 60:
        raise MinuteError("minutes outside 1..60")
    return value

def __failure_details(text):
    try:
        parse_minutes(text)
    except MinuteError as error:
        return (str(error), type(error.__cause__).__name__)
    return None

def save_note(path, text, append=False):
    mode = "a" if append else "w"
    with open(path, mode, encoding="utf-8") as handle:
        return handle.write(text)

def __read_note(path):
    with open(path, "r", encoding="utf-8") as handle:
        return handle.read()

import argparse

def parse_minutes(arguments):
    parser = argparse.ArgumentParser(prog="study", add_help=False, allow_abbrev=False)
    parser.add_argument("--minutes", type=int, default=10, choices=range(1, 61))
    options = parser.parse_args(arguments)
    return options.minutes

def __rejects_arguments(arguments):
    try:
        parse_minutes(arguments)
    except SystemExit as error:
        return error.code == 2
    return False

